// The trophy the plugin's own web UI falls back to, for a name nothing here recognises.
const FALLBACK = ACHIEVEMENT_ICON_PATHS.emoji_events;

export const achievementIconPath = (name) => {
	const key = String(name || '').trim().toLowerCase();
	return ACHIEVEMENT_ICON_PATHS[key] || MATERIAL_ICON_PATHS[key] || FALLBACK;
};
